    shape.lineTo(-0.28, 1.35); 
    shape.lineTo(-0.35, 1.35); 
    shape.lineTo(-0.35, 0.6); 
    shape.lineTo(-0.55, 0.6); 
    shape.lineTo(-0.55, 1.55); 
